CREATE TABLE IF NOT EXISTS public.gateway_recovery_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, attempt_id uuid NOT NULL, transaction_id uuid NULL, gateway_id text NOT NULL, provider text NOT NULL, idempotency_key text NOT NULL, failure_class text NOT NULL, external_transaction_id text NULL, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, next_retry_at timestamptz NOT NULL DEFAULT now(), last_error text NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT gateway_recovery_queue_status_ck CHECK (status IN ('queued','processing','resolved','not_found','dead_letter')), CONSTRAINT gateway_recovery_queue_failure_ck CHECK (failure_class IN ('timeout','technical','unavailable','unknown')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_gateway_recovery_queue_attempt ON public.gateway_recovery_queue(user_id,attempt_id);
CREATE INDEX IF NOT EXISTS idx_gateway_recovery_queue_ready ON public.gateway_recovery_queue(status,next_retry_at);
CREATE INDEX IF NOT EXISTS idx_gateway_recovery_queue_tenant ON public.gateway_recovery_queue(user_id,created_at DESC);
ALTER TABLE public.gateway_recovery_queue ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS gateway_recovery_queue_service_only ON public.gateway_recovery_queue;
CREATE POLICY gateway_recovery_queue_service_only ON public.gateway_recovery_queue FOR ALL TO service_role USING (true) WITH CHECK (true);
REVOKE ALL ON public.gateway_recovery_queue FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.gateway_recovery_queue TO service_role;
CREATE OR REPLACE FUNCTION public.guard_gateway_ambiguous_failover() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_exists boolean; v_base text; BEGIN v_base:=split_part(NEW.idempotency_key,':',1); IF NEW.idempotency_key IS NULL OR v_base='' THEN RETURN NEW; END IF; SELECT EXISTS (SELECT 1 FROM public.gateway_payment_attempts a WHERE a.user_id=NEW.user_id AND split_part(a.idempotency_key,':',1)=v_base AND a.id<>NEW.id AND a.failure_class IN ('timeout','technical','unavailable','unknown')) INTO v_exists; IF v_exists THEN RAISE EXCEPTION 'ambiguous_gateway_attempt_requires_status_recovery'; END IF; IF NEW.failure_class IN ('timeout','technical','unavailable','unknown') THEN INSERT INTO public.gateway_recovery_queue(user_id,attempt_id,transaction_id,gateway_id,provider,idempotency_key,failure_class,external_transaction_id) VALUES (NEW.user_id,NEW.id,NEW.transaction_id,NEW.gateway_id,NEW.gateway_name,NEW.idempotency_key,NEW.failure_class,NEW.external_transaction_id) ON CONFLICT (user_id,attempt_id) DO NOTHING; END IF; RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS trg_gateway_ambiguous_failover_guard ON public.gateway_payment_attempts;
CREATE TRIGGER trg_gateway_ambiguous_failover_guard BEFORE INSERT ON public.gateway_payment_attempts FOR EACH ROW EXECUTE FUNCTION public.guard_gateway_ambiguous_failover();
REVOKE EXECUTE ON FUNCTION public.guard_gateway_ambiguous_failover() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.guard_gateway_ambiguous_failover() TO service_role;
